-- Saison record (research 13 §6, Fahrplan R7): event_season + event_season_anchor, template_item.scope,
-- checklist/task/permit.season_id. Generated by drizzle-kit, plus one HAND-WRITTEN guard (marked below).
-- Existing rows need no data change: template items default to scope 'event', the new season_id columns are null.
CREATE TYPE "app"."event_season_status" AS ENUM('planning', 'dates_set', 'closed');--> statement-breakpoint
CREATE TYPE "app"."template_item_scope" AS ENUM('event', 'season');--> statement-breakpoint
CREATE TABLE "app"."event_season" (
	"id" uuid PRIMARY KEY NOT NULL,
	"preset_id" uuid NOT NULL,
	"season" integer NOT NULL,
	"expected_start" date NOT NULL,
	"status" "app"."event_season_status" DEFAULT 'planning' NOT NULL,
	"notes" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"archived_at" timestamp with time zone,
	CONSTRAINT "event_season_presetId_season_unique" UNIQUE("preset_id","season"),
	CONSTRAINT "event_season_year" CHECK ("app"."event_season"."season" between 1900 and 9999)
);
--> statement-breakpoint
CREATE TABLE "app"."event_season_anchor" (
	"id" uuid PRIMARY KEY NOT NULL,
	"season_id" uuid NOT NULL,
	"key" text NOT NULL,
	"date" date NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "event_season_anchor_seasonId_key_unique" UNIQUE("season_id","key")
);
--> statement-breakpoint
