ALTER TABLE "app"."event_season" ADD CONSTRAINT "event_season_preset_id_event_preset_id_fk" FOREIGN KEY ("preset_id") REFERENCES "app"."event_preset"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "app"."event_season_anchor" ADD CONSTRAINT "event_season_anchor_season_id_event_season_id_fk" FOREIGN KEY ("season_id") REFERENCES "app"."event_season"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
