-- HAND-WRITTEN BEGIN: a checklist now needs exactly one owner (event, permit or season). The app never made a
-- checklist without one (event and permit deletion cascade), so none should exist. If one does, stop with a
-- readable message instead of a bare check violation, so it is looked at before anything gets deleted.
DO $$
BEGIN
	IF EXISTS (SELECT 1 FROM "app"."checklist" WHERE "event_id" IS NULL AND "permit_id" IS NULL) THEN
		RAISE EXCEPTION '0022_saison: % checklist(s) without an event or a permit; give them an owner or delete them first',
			(SELECT count(*) FROM "app"."checklist" WHERE "event_id" IS NULL AND "permit_id" IS NULL);
	END IF;
END $$;--> statement-breakpoint
-- HAND-WRITTEN END
ALTER TABLE "app"."checklist" ADD CONSTRAINT "checklist_one_owner" CHECK (num_nonnulls("app"."checklist"."event_id", "app"."checklist"."permit_id", "app"."checklist"."season_id") = 1);